<?php
declare(strict_types=1);
final class Csrf { public static function token():string{$now=time();$ttl=(int)AppContext::config('security.csrf_ttl',3600);if(!isset($_SESSION['_csrf'],$_SESSION['_csrf_at'])||$now-(int)$_SESSION['_csrf_at']>$ttl){$_SESSION['_csrf']=bin2hex(random_bytes(32));$_SESSION['_csrf_at']=$now;}return $_SESSION['_csrf'];} public static function verify(?string $token):bool{return $token!==null&&!empty($_SESSION['_csrf'])&&hash_equals((string)$_SESSION['_csrf'],$token);} public static function requireValid(?string $token):void{if(!self::verify($token)){http_response_code(419);exit('Invalid or expired security token.');}} }
